    #[tokio::test]
    async fn test_template_repository_exists() {
        let mut repo = MockTemplateRepository::new();
        let template = make_test_template("exists-check");

        let exists_before = repo.exists("exists-check").await.expect("exists check should succeed");
        assert!(!exists_before, "Template should not exist before creation");

        repo.create(template, false)
            .await
            .expect("Create should succeed");

        let exists_after = repo.exists("exists-check").await.expect("exists check should succeed");
        assert!(exists_after, "Template should exist after creation");
    }

    #[tokio::test]
    async fn test_template_repository_delete() {
        let mut repo = MockTemplateRepository::new();
        let template = make_test_template("to-delete");

        repo.create(template, false)
            .await
            .expect("Create should succeed");

        repo.delete("to-delete")
            .await
            .expect("Delete should succeed");

        let exists = repo.exists("to-delete").await.expect("exists check should succeed");
        assert!(!exists, "Template should not exist after deletion");
    }

